from collections import Counter

def transform(grid):
    H, W = len(grid), len(grid[0])
    out = [r[:] for r in grid]

    def irregular(row):
        nz = [c for c in row if c != 0]
        if not nz:
            return False
        has_zero = any(c == 0 for c in row)
        return has_zero or len(set(nz)) > 1

    i = 0
    while i < H:
        if irregular(grid[i]):
            j = i
            while j < H and irregular(grid[j]):
                j += 1
            row = grid[i]
            zs = [k for k, c in enumerate(row) if c == 0]
            if zs:
                for k in range(zs[-1] + 1, W):
                    if row[k] != 0:
                        out[i][k] = 1
            else:
                cnt = Counter(row)
                minority = min(cnt, key=cnt.get)
                if cnt[minority] < max(cnt.values()):
                    for k, c in enumerate(row):
                        if c == minority:
                            out[i][k] = 1
            i = j
        else:
            i += 1
    return out
