from collections import Counter

def transform(grid):
    H, W = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = Counter(c for row in grid for c in row)
    bg = counts.most_common(1)[0][0]

    def noise_cols(row):
        return [i for i, c in enumerate(row) if c != bg]

    # find bands of consecutive noisy rows
    i = 0
    while i < H:
        if any(c != bg for c in grid[i]):
            j = i
            while j < H and any(c != bg for c in grid[j]):
                j += 1
            band = range(i, j)
            lasts = {r: noise_cols(grid[r])[-1] for r in band}
            M = max(lasts.values())
            if M < W - 1:
                ref = noise_cols(grid[i])  # rhythm from first row of band
                # split into runs
                runs = []
                cur = [ref[0]]
                for p in ref[1:]:
                    if p == cur[-1] + 1:
                        cur.append(p)
                    else:
                        runs.append(cur)
                        cur = [p]
                runs.append(cur)
                lastrun = runs[-1]
                if len(lastrun) >= 2:
                    cols = list(range(lastrun[-1] + 1, W))
                elif len(runs) >= 2 and lastrun[0] - runs[-2][-1] >= 2:
                    s = lastrun[0] - runs[-2][-1]
                    cols = list(range(lastrun[0] + s, W, s))
                else:
                    cols = list(range(lastrun[-1] + 1, W))
                for r in band:
                    if lasts[r] == M:
                        for c in cols:
                            out[r][c] = 1
            i = j
        else:
            i += 1
    return out
